update public.preguntas set
    explicacion = v.explicacion::text,
    norma = v.norma::text
from (values
('cap-8b23bda62f16', 'Los sobreesfuerzos son el accidente más común en el transporte porque la carga y descarga de mercancías, así como la manipulación de elementos pesados del vehículo, implican un gran esfuerzo físico. Estas tareas repetitivas o mal ejecutadas suelen provocar lesiones musculares o esqueléticas. Aunque la caída de objetos al manipularlos también ocurre, los sobreesfuerzos son estadísticamente más frecuentes y afectan a más trabajadores.', NULL),
('cap-8b440924f37c', 'Los discos de tacógrafo analógico están diseñados para registrar la actividad de un conductor durante un periodo máximo de 24 horas. Utilizar un disco durante 48 horas no es correcto porque excede el tiempo para el que está homologado, lo que impediría un registro claro y preciso de los datos. El conductor debe colocar el disco al inicio de su jornada y mantenerlo en el tacógrafo hasta el final, asegurando que cada jornada quede registrada en un disco diferente.', 'Reglamento Comunitario (UE) 165/2014 Anexo I, apartado IV, a.2'),
('cap-8b5545a5574c', 'El Espacio Schengen está formado exclusivamente por países europeos, tanto de la Unión Europea como otros que se han adherido a este acuerdo. Su objetivo es permitir la libre circulación de personas entre los estados miembros sin controles fronterizos internos. La inclusión de Iberoamérica, el norte de África o Hispanoamérica en el Espacio Schengen es incorrecta, ya que estos territorios no forman parte de este acuerdo de libre circulación.', 'Convenio Aplicación del Acuerdo de Schengen Art. 140'),
('cap-8b6aa7b52c3f', 'Los períodos de espera por prohibiciones de circular son tiempo de presencia si se conocen de antemano, ya que el conductor está a disposición de la empresa pero sin realizar trabajo efectivo. En cambio, la carga, descarga, limpieza, mantenimiento y las tareas de seguridad del vehículo y la carga son tiempo de trabajo efectivo, no de presencia. No confundas el tiempo de presencia con el tiempo de trabajo efectivo, que son conceptos distintos aunque ambos computan en la jornada.', NULL),
('cap-8b6c541b202e', 'En las empresas pequeñas de transporte, el empresario suele ser autónomo o tener pocos empleados, por lo que es habitual que él mismo se ponga al volante para realizar los transportes. Las gestiones administrativas, fiscales o de Seguridad Social, aunque importantes, a menudo se externalizan a asesorías para ahorrar tiempo y costes. Un empresario pequeño no puede permitirse tener un conductor contratado si él mismo puede hacer el trabajo de conducción.', NULL),
('cap-8bc67310046b', 'Los elementos de seguridad pasiva, como el airbag o el cinturón de seguridad, están diseñados para actuar por sí solos en el momento de un accidente, sin que el conductor o los ocupantes tengan que hacer nada. Su función es minimizar los daños una vez que el suceso ya ha ocurrido. La idea es que funcionen de forma automática cuando se detecta el impacto. No requieren ninguna acción previa o física por parte del conductor o los ocupantes para activarse.', NULL),
('cap-8bdfd1db1856', 'El Convenio CMR, en su Artículo 18, establece que es el transportista quien debe probar que la pérdida, avería o retraso de la mercancía se debe a alguna de las causas de exención de responsabilidad que contempla. Es su obligación demostrar que el daño no fue por su culpa. No corresponde al remitente ni al destinatario probar la causa del daño, ya que ellos no tienen el control de la mercancía durante el transporte.', 'Convenio CMR Art. 18'),
('cap-8bec97bb5a20', 'Para que el motor gire a menos revoluciones y consuma menos, debes seleccionar la marcha más larga posible. Esto permite que el motor trabaje en su zona de par óptimo, que es donde es más eficiente. Reducir la relación de compresión o la carrera del pistón son modificaciones mecánicas del motor que no se pueden hacer durante la conducción.', NULL),
('cap-8bfed77ed99d', 'Un fuego con brasas es un fuego de tipo A, es decir, de combustibles sólidos. Para extinguir este tipo de fuegos, lo más efectivo es reducir su temperatura por debajo del punto de ignición. Esto se consigue mediante el enfriamiento, normalmente con agua, que absorbe el calor y apaga las brasas. La ignición es el proceso contrario, es decir, iniciar el fuego.', NULL),
('cap-8c26242ab11f', 'Mantener los cristales de las ventanillas subidos es crucial porque reduce la resistencia aerodinámica del vehículo. Al circular con las ventanillas bajadas, el aire entra en la cabina y crea turbulencias, lo que obliga al motor a trabajar más para mantener la velocidad y, por tanto, aumenta el consumo de carburante. La zona verde del cuentarrevoluciones indica el rango de eficiencia óptima del motor, no la de mayor consumo. Instalar alerones que aumenten el coeficiente aerodinámico es incorrecto, ya que los alerones suelen buscar mejorar la estabilidad o la carga aerodinámica, y un mayor coeficiente aerodinámico siempre implica más resistencia y, por tanto, más consumo.', NULL),
('cap-8c3e41bedded', 'La potencia de un motor se mide en caballos de vapor (CV) o en kilovatios (kW), que son las unidades estándar para expresar la capacidad de trabajo de un motor. Los caballos fiscales son una medida para calcular impuestos, no la potencia real. Los newtons miden fuerza, y los kilómetros por hora miden velocidad, no potencia.', NULL),
('cap-8c57c5bad78b', 'El círculo de Kamm explica que el agarre total disponible de un neumático se reparte entre las fuerzas longitudinales (aceleración o frenado) y las fuerzas laterales (guiado o dirección). Si aumentas la fuerza de frenado, estás utilizando más agarre en sentido longitudinal, por lo que necesariamente dispones de menos agarre para la fuerza de guiado lateral. La fuerza de guiado no desaparece por completo, solo disminuye, a menos que el frenado sea tan extremo que se bloquee la rueda.', NULL),
('cap-8c590b2abb31', 'Los vehículos utilizados por el Ejército, la Policía o los bomberos en el ejercicio de sus funciones están exentos del uso de tacógrafo. Esta exención se aplica porque el transporte se realiza como parte de su función propia y bajo su responsabilidad, según el Reglamento Comunitario (CE) 561/2006 Art. 3.c. No existe un "tacógrafo especial" u "oficial" para estos vehículos, ni están obligados a usar el tacógrafo digital.', 'Reglamento Comunitario (CE) 561/2006 Art. 3.c'),
('cap-8c90e2449d4d', 'La somnolencia diurna crónica es un síntoma clave de que hay un problema subyacente con el sueño, es decir, un trastorno del sueño. Estos trastornos impiden un descanso reparador, lo que se manifiesta en el día como una necesidad incontrolable de dormir. Aunque la fatiga puede ser una consecuencia, la causa directa de la somnolencia crónica son los trastornos del sueño. El estrés y la ingesta de alcohol pueden afectar el sueño, pero no son la causa principal de la somnolencia diurna crónica.', NULL),
('cap-8cb7184c034e', 'Las reclamaciones derivadas de un contrato de transporte internacional de mercancías por carretera, regulado por el Convenio CMR, prescriben en el plazo de un año. Este plazo es el establecido específicamente en el Convenio CMR Art. 32 para la mayoría de las acciones. La opción de dos años es incorrecta, ya que ese plazo se aplica solo en casos de dolo o falta equivalente.', 'Convenio CMR Art. 32'),
('cap-8cbe0862f9b5', 'Recorrer un trayecto poco conocido exige una mayor concentración y atención a las señales, la navegación y las posibles desviaciones, lo que incrementa el esfuerzo mental y, por tanto, la fatiga. Circular por una vía rápida, aunque pueda parecer monótono, generalmente es menos exigente mentalmente que un trayecto desconocido. Una amortiguación defectuosa o una presión defectuosa de los neumáticos afectan más a la comodidad y la seguridad, pero no son la causa principal de un aumento significativo de la fatiga mental como lo es la incertidumbre de una ruta nueva.', NULL),
('cap-8cc4997aa1d3', 'Sí, la elección de la relación de marchas influye directamente en el consumo de carburante. Usar la marcha adecuada permite que el motor trabaje en su rango óptimo de revoluciones, lo que se traduce en una mayor eficiencia y menor gasto de combustible. Circular con una marcha demasiado larga o demasiado corta para la velocidad y la carga del vehículo fuerza el motor y aumenta el consumo. No es cierto que solo influya en pendientes o en llano, ya que la gestión de marchas es crucial en cualquier situación de conducción.', NULL),
('cap-8ccf20c660b0', 'El tacógrafo registra la distancia recorrida, la velocidad del vehículo y la actividad del conductor, como el tiempo de conducción. Estos son datos fundamentales para el control de los tiempos de trabajo y descanso. El Reglamento Comunitario (UE) 165/2014 Art. 4.3 especifica que los tacógrafos digitales deben registrar estos datos. Por lo tanto, todas las opciones mencionadas son correctas.', 'Reglamento Comunitario (UE) 165/2014 Art. 4.3'),
('cap-8cd9075aa251', 'El seguro obligatorio cubre los daños a terceros, pero no los propios del conductor responsable del accidente. Es decir, el seguro obligatorio no cubre los daños personales que sufra el conductor que ha provocado el siniestro. La cobertura del seguro obligatorio sí alcanza a la persona propietaria del vehículo causante del accidente, siempre que no sea el conductor responsable.', NULL),
('cap-8cef7debc636', 'El estilo de conducción es el factor más determinante en el consumo de carburante. Una conducción eficiente, anticipándose al tráfico y usando correctamente las marchas, reduce significativamente el gasto. El tipo de ralentizador no influye directamente en el consumo, ya que su función es frenar el vehículo, no propulsarlo.', NULL),
('cap-8d41f2ffba93', 'Los ansiolíticos, sedantes e hipnóticos son medicamentos diseñados para actuar sobre el sistema nervioso central, y su efecto principal o secundario es la reducción de la actividad cerebral, lo que se traduce en somnolencia. Por lo tanto, cualquiera de ellos puede afectar seriamente la capacidad de conducir. Es crucial que los conductores profesionales sean conscientes de los efectos de estos fármacos.', NULL),
('cap-8db2f3b0e966', 'La caída de objetos al manipularlos es el accidente menos frecuente porque los conductores profesionales suelen estar más expuestos a riesgos relacionados con la conducción y el entorno del vehículo. Las caídas al mismo nivel, los atropellos y la exposición a vibraciones son riesgos mucho más comunes en la actividad diaria del transporte. Aunque la manipulación de objetos es parte del trabajo, los protocolos de seguridad y la naturaleza de las cargas suelen minimizar este tipo de incidentes en comparación con otros peligros inherentes al sector.', NULL),
('cap-8dd63e1723ba', 'Los peajes se establecen para cubrir los gastos directos de mantener operativa la carretera, como el mantenimiento, la conservación y la gestión diaria. Estos son los costes de explotación. La previsión de desgaste de la infraestructura ya está incluida en los costes de explotación, que contemplan el mantenimiento necesario para contrarrestarlo. Las previsiones de inversión en nuevas infraestructuras no se suelen financiar directamente con los peajes de las infraestructuras existentes, sino con otras fuentes de financiación.', NULL),
('cap-8de6db5afadb', 'Para trazar una curva correctamente, es fundamental considerar la anchura del carril para no invadir el contrario o salirte, y el tipo de firme, ya que un asfalto mojado o en mal estado reduce la adherencia y exige más precaución. La distancia con otros vehículos es importante para la seguridad general, pero no determina directamente cómo trazar la curva. Los deflectores son elementos aerodinámicos que no influyen en el trazado de una curva.', NULL),
('cap-8debe3ffd7db', 'Abandonar el lugar de un accidente del que se es responsable puede ser considerado un delito de omisión del deber de socorro, o incluso un delito de fuga si se hace para eludir responsabilidades. No es solo una infracción administrativa, ya que las consecuencias pueden ser mucho más graves. La idea de que solo es delito si se considera omisión de socorro es incompleta, porque hay otras figuras delictivas aplicables.', NULL),
('cap-8dfa24dff4d5', 'Si la fuerza que el motor puede generar es menor que la resistencia que se opone al movimiento, el motor no tendrá suficiente potencia para superar esa resistencia y se detendrá. Es como intentar empujar una pared: si no tienes fuerza suficiente, no la moverás y te quedarás parado. Las opciones que sugieren que el vehículo se moverá con ciertas pendientes son incorrectas, ya que la relación de fuerzas es la que determina el movimiento, no un porcentaje de pendiente específico.', NULL),
('cap-8e06a14f3624', 'El sistema TSR (Traffic Sign Recognition) está diseñado para identificar las señales de tráfico que encuentra el vehículo en la carretera. Su función principal es mostrar esta información al conductor, generalmente en el panel de instrumentos, para que esté al tanto de los límites de velocidad, prohibiciones u otras indicaciones. No interviene directamente en la velocidad ni en la trayectoria del vehículo, solo informa. Reducir la velocidad ante un riesgo de colisión es función de otros sistemas como el AEB.', NULL),
('cap-8e08987720f6', 'El freno motor es una técnica que aprovecha la resistencia interna del propio motor para disminuir la velocidad del vehículo, especialmente útil en descensos prolongados para evitar el sobrecalentamiento de los frenos de servicio. Se consigue al levantar el pie del acelerador y, si es necesario, reducir una o varias marchas. La utilización del pedal de freno es el freno de servicio, no el freno motor.', NULL),
('cap-8e1543404310', 'La elección de la relación de la caja de cambios se basa principalmente en el perfil de la carretera para mantener el motor en su rango de revoluciones óptimo, asegurando la potencia y el par necesarios. En una subida, necesitarás una marcha más corta para tener más fuerza, mientras que en un llano o bajada, podrás usar una marcha más larga para ahorrar combustible. El rozamiento mecánico es una característica del vehículo, no una variable que el conductor elija.', NULL),
('cap-8e5f6b70ab59', 'Si el reclamante no acude a la vista oral, se entiende que ya no tiene interés en seguir adelante con su reclamación. Por eso, la Junta Arbitral considera que ha desistido y el procedimiento se archiva. No se trata de una sanción económica, sino de una consecuencia procesal por la incomparecencia.', NULL),
('cap-8e6b470e1d1c', 'El sistema LDW, o aviso de salida de carril, está diseñado para alertar al conductor cuando el vehículo se desvía involuntariamente de su carril. Se activa precisamente cuando el sistema detecta que el vehículo está cruzando las líneas del carril sin que el conductor haya indicado previamente la maniobra con el intermitente. Si se activa el intermitente, el sistema entiende que la salida de carril es intencionada y no emite la alerta. La opción de la presión del neumático se refiere al sistema TPMS, que es diferente.', NULL),
('cap-8e6c53ca32b1', 'Los conductores profesionales están expuestos a factores como las vibraciones, las posturas estáticas prolongadas y el estrés, que contribuyen a una mayor incidencia de problemas de salud. Esto se traduce en que la duración de las bajas laborales en el transporte es superior a la media de otros sectores. Pensar que es inferior es un error, ya que las condiciones de trabajo específicas del sector no favorecen una menor duración de las bajas.', NULL),
('cap-8e6f4a5128f0', 'Las sociedades cooperativas pueden ser de primero y segundo grado. Así lo establece la Ley 27/1999 Art. 1.4, que es la normativa que regula estas sociedades. No existen cooperativas de tercer o cuarto grado, ni tampoco se limitan solo a las de primer grado.', 'Ley 27/1999 Art. 1.4'),
('cap-8e71cbc99d69', 'Es fundamental no colocar las mercancías más pesadas sobre las ligeras para evitar aplastamientos y daños. Una buena estiba busca distribuir el peso de manera uniforme y segura. Cargar mercancías peligrosas junto a otras que no lo sean es incorrecto por los riesgos de contaminación o reacción. Dejar huecos entre mercancías de distintos embalajes puede provocar movimientos indeseados y daños durante el transporte.', NULL),
('cap-8e9810d17187', 'El Reglamento Comunitario (CE) 1072/2009 Art. 8 establece que, si la entrada en el Estado de acogida se produce en vacío, se pueden realizar hasta tres transportes de cabotaje consecutivos. Sin embargo, hay una condición importante: solo se permite un transporte de cabotaje por Estado miembro en los tres días siguientes a la entrada en vacío. La opción de "ninguno" es incorrecta, ya que la normativa sí permite realizar cabotaje incluso si la entrada inicial es en vacío, bajo las condiciones mencionadas.', 'Reglamento Comunitario (CE) 1072/2009 Art. 8'),
('cap-8e9a6ca9735a', 'Cuando hay varias Juntas Arbitrales que podrían conocer de un mismo asunto, la que se haya planteado primero es la que tiene la competencia. Esto evita que el mismo caso se tramite en diferentes sitios a la vez, lo que sería un lío. No se decide por acuerdo entre las Juntas, ni por el domicilio del demandante o de la empresa, sino por el principio de "primero en el tiempo, primero en el derecho".', NULL),
('cap-8ec534240ead', 'Puedes conducir sin tarjeta de conductor durante 15 días naturales si el vehículo lleva tacógrafo digital. Este plazo se puede alargar si necesitas devolver el vehículo a la base de la empresa y puedes demostrar que no fue posible usar la tarjeta. La opción de 2 meses o más es incorrecta, ya que el plazo máximo es de 15 días en condiciones normales.', NULL),
('cap-8ee3d7972a05', 'El Acuerdo ATP, como su propio título indica, regula el transporte internacional de mercancías perecederas y los vehículos especiales que se utilizan para ello. Su objetivo es asegurar que estos productos lleguen en condiciones óptimas. No tiene relación con el transporte de personas con movilidad reducida, ni con el transporte combinado, ni es un acuerdo aduanero.', 'Acuerdo ATP Título'),
('cap-8efbcad91f08', 'Los transportistas tienen la obligación de verificar que los nacionales de terceros países que transportan para entrar en el Espacio Schengen poseen la documentación necesaria, ya sea un documento de viaje o un visado. Esta responsabilidad está claramente establecida en el Convenio Aplicación del Acuerdo de Schengen Art. 26.1.b. No es una tarea exclusiva de la policía de fronteras, sino una obligación que recae también sobre el transportista. La idea de que los transportistas solo se ocupan de los objetos y no de las personas es incorrecta.', 'Convenio Aplicación del Acuerdo de Schengen Art. 26.1.b'),
('cap-8f02cb301c6f', 'El Convenio TIR es el que facilita el paso de mercancías por las fronteras, ya que permite que los vehículos precintados crucen los países sin necesidad de inspecciones aduaneras en cada frontera intermedia. Esto agiliza mucho el transporte internacional. El convenio CMR se refiere al contrato de transporte internacional por carretera, no a la simplificación aduanera. El ADR regula el transporte de mercancías peligrosas, y el ASOR no es un convenio relacionado con la simplificación del paso de fronteras.', 'Convenio TIR Preámbulo'),
('cap-8f075008e374', 'El Reglamento Comunitario (UE) 165/2014 Art. 36.2 establece claramente que el conductor debe llevar consigo su tarjeta de conductor, los registros manuales o impresiones que haya realizado, y las hojas de registro si ha conducido un vehículo con tacógrafo analógico en el período requerido. Por tanto, todas las opciones son correctas y necesarias para el control. La opción que menciona solo los discos-diagrama en un supuesto específico es incompleta, ya que el conductor debe llevar más documentación.', 'Reglamento Comunitario (UE) 165/2014 Art. 36.2'),
('cap-8f188d952aec', 'La Directiva 2003/59/CE Art. 1 establece una formación obligatoria para ciertos conductores profesionales, que es adicional a la obtención del permiso de conducir. Esta formación, conocida como CAP, asegura que los conductores mantengan sus conocimientos actualizados y mejoren sus habilidades. No es exclusiva de conductores de autobús ni solo para mercancías perecederas, sino que abarca a la mayoría de los conductores profesionales de transporte de mercancías y viajeros. La idea de que no existe ninguna obligación de formación adicional es incorrecta, ya que el CAP es un requisito legal para ejercer la profesión.', 'Directiva 2003/59/CE Art. 1'),
('cap-8f1f8bfc3120', 'Una autorización CEMT permite realizar transporte internacional de mercancías por carretera entre los países que son miembros de la Conferencia Europea de Ministros de Transporte. Es importante recordar que esta autorización no cubre el transporte con países que no son miembros de la CEMT. Tampoco permite realizar transporte de cabotaje, que es el transporte de mercancías dentro de un mismo país por un transportista extranjero.', NULL),
('cap-8f38a81fbab5', 'En las inspecciones en carretera, el conductor es el representante de la empresa para la documentación que debe llevarse a bordo del vehículo y la información del servicio. Esto lo establece la Ley 16/1987 Art. 33. La opción de que cualquier empleado de la empresa sea el representante es incorrecta, ya que la ley especifica claramente que es el conductor quien asume esa función en carretera.', 'Ley 16/1987 Art. 33'),
('cap-8f6866b861c5', 'Aprovechar la inercia del vehículo, por ejemplo, en bajadas o al acercarse a una detención, permite que el motor trabaje menos o incluso que no consuma combustible si se levanta el pie del acelerador y se mantiene una marcha engranada. Esto reduce el esfuerzo del motor y, por tanto, su consumo. Circular con marchas cortas o siempre en primera velocidad fuerza el motor a trabajar a altas revoluciones para poca velocidad, lo que aumenta el consumo. Utilizar el menor par motor posible no es eficiente; lo ideal es trabajar en la zona de par máximo para optimizar el consumo.', NULL),
('cap-8fae86614123', 'Sí, siempre se pueden anotar los datos de los testigos en la declaración amistosa de accidente. La información de los testigos es muy valiosa para aclarar cómo ocurrió el siniestro, ya que aportan una visión imparcial de los hechos. No es cierto que solo se puedan anotar si hay heridos o si son agentes de la autoridad; cualquier testigo puede y debe ser incluido.', NULL),
('cap-8fdefe718fe5', 'Las empresas transportistas deben enviar información de los pasajeros que vienen de fuera del Espacio Schengen, sin importar el medio de transporte. Esto incluye rutas por aire, mar o tierra. No se limita solo a un tipo de vía, ya que el control de fronteras es necesario en todos los puntos de entrada.', NULL),
('cap-902dafd0c21c', 'El aislamiento social es un factor de estrés importante, especialmente en rutas largas donde el conductor pasa mucho tiempo solo. El riesgo económico personal también genera estrés, ya que un transportista autónomo depende directamente de su trabajo para vivir. La prolongación de las jornadas laborales, con menos tiempo de descanso, es una causa directa de fatiga y estrés. Por lo tanto, todos estos factores contribuyen al estrés del conductor profesional.', NULL),
('cap-903c75bbe4db', 'Lo primero es asegurar la zona para evitar nuevos accidentes o que la situación empeore. Esto protege tanto a los implicados como a los que van a ayudar. Una vez que la zona es segura, ya se puede atender a las víctimas y pedir ayuda. Ayudar a las víctimas sin asegurar la zona primero puede poner en peligro a más personas.', NULL),
('cap-90404fb5ddef', 'Una relación de arranque que permite una salida suave y casi sin acelerar es fundamental para el ahorro de energía. Al arrancar de esta manera, se evita un consumo excesivo de combustible que se produce al demandar mucha potencia al motor desde el inicio. Esto reduce el esfuerzo del motor y, por tanto, su consumo. La opción de aumentar la energía potencial no tiene relación directa con el ahorro de energía en el arranque.', NULL),
('cap-906bc789ceed', 'Cuando se detecta un exceso de conducción diario grave en un control en carretera, los agentes deben denunciar la infracción y, además, inmovilizar el vehículo. La inmovilización se mantiene hasta que el conductor haya cumplido con el descanso obligatorio que le corresponde. Esto está recogido en la Ley 16/1987 Art. 143.4. No es correcto pensar que no es un hecho denunciable, ya que el incumplimiento de los tiempos de conducción es una infracción grave que afecta directamente a la seguridad vial.', 'Ley 16/1987 Art. 143.4'),
('cap-90727554e347', 'La no presentación de los discos de tacógrafo de los 28 días anteriores es una infracción muy grave. La Ley 16/1987, en su Artículo 140.35, establece que la falta de presentación de la documentación de control de los tiempos de conducción y descanso se considera una infracción muy grave. No importa si faltan pocos o muchos días, la obligación es presentar todos los registros del periodo requerido.', 'Ley 16/1987 Art. 140.35'),
('cap-9082a7504451', 'Un incidente es un suceso que altera el desarrollo normal del transporte, pero sin llegar a ser un accidente grave. Una circunstancia de tráfico que no pone en peligro grave a las personas encaja en esta definición. El incendio del motor, un choque frontal o un vuelco son sucesos de mucha mayor gravedad que se clasifican directamente como accidentes.', NULL),
('cap-9083b788df5b', 'Observar las revoluciones del motor te permite cambiar de marcha en el momento óptimo, aprovechando el par motor y evitando que el motor trabaje forzado o a revoluciones excesivas, lo que reduce el consumo. Circular con una presión de inflado inferior a la recomendada aumenta la resistencia a la rodadura y, por tanto, el consumo de carburante. Esperar con el motor arrancado sin circular o acelerar en vacío para que el motor alcance la temperatura son prácticas que gastan combustible innecesariamente sin mover el vehículo.', NULL),
('cap-90b8363b644d', 'El alumbrado del vehículo debe usarse siempre que la visibilidad se vea reducida por cualquier factor, como niebla, lluvia intensa o túneles, para ver y ser visto. No se limita a un horario específico, ya que las condiciones de baja visibilidad pueden darse en cualquier momento del día. Usar las luces solo entre la salida y la puesta del sol es un error, porque de día también puede haber poca visibilidad.', NULL),
('cap-90ea4c91e0a5', 'El grado de rozamiento en un camión depende directamente de cómo esté la calzada y de qué material sea. Una calzada mojada o con hielo, o una superficie de tierra, no ofrecen el mismo agarre que una calzada seca y asfaltada. La fuerza termotecnia lateral no existe como concepto en la física del vehículo, y el porcentaje de nitrógeno no influye en el rozamiento.', NULL),
('cap-90ebd2511f4c', 'Respetar los métodos de trabajo es una obligación directa del trabajador, ya que debe seguir las instrucciones del empresario para usar adecuadamente los medios y equipos. La Ley 31/1995 Art. 29 establece claramente que los trabajadores deben cumplir las medidas de prevención adoptadas. La formación e información es una obligación del empresario, no del trabajador.', 'Ley 31/1995 Art. 29'),
('cap-912a74b161d3', 'Un operador logístico puede utilizar tanto vehículos propios como ajenos para desarrollar su actividad. La Ley 16/1987 Art. 122 establece claramente que pueden emplear infraestructuras, tecnología y medios propios o ajenos. Esto les permite adaptarse a las necesidades de sus clientes y a la demanda del mercado. La idea de que solo pueden usar vehículos propios es incorrecta, ya que limitaría su capacidad operativa y la flexibilidad que caracteriza a su servicio.', 'Ley 16/1987 Art. 122'),
('cap-916fb5e8949d', 'Todos los medicamentos que puedan afectar a la conducción deben llevar una indicación clara en su etiquetado para advertir al conductor. Esta medida de seguridad es fundamental para prevenir accidentes. La opción que indica que solo los que contienen psicotrópicos o solo los que requieren receta médica deben llevar esta indicación es incorrecta, ya que la advertencia se aplica a cualquier medicamento con efectos sobre la capacidad de conducir, independientemente de su composición o forma de dispensación.', 'RD 1345/2007 Anexo IV'),
('cap-919696212c25', 'El freno en el escape actúa cerrando la salida de gases del motor, lo que genera una contrapresión que retiene el giro del motor. Como el motor está conectado a las ruedas motrices a través de la transmisión, la fuerza de frenado se transmite directamente a estas ruedas. Las ruedas directrices no tienen conexión directa con el motor para este tipo de frenado. No se frenan todas las ruedas porque el sistema no actúa sobre los frenos de servicio de cada rueda.', NULL),
('cap-91e76a3d5e9b', 'Ante una hemorragia, lo primero es aplicar presión directa sobre la herida con un trapo limpio para intentar detener el sangrado. Si el trapo se empapa, no lo retires; simplemente coloca otro trapo limpio encima y sigue presionando. Esto ayuda a formar un coágulo y a controlar la pérdida de sangre. No actuar ante una hemorragia es un error grave, ya que una intervención rápida puede ser vital.', NULL),
('cap-91ff5a461ab2', 'Ante un aviso de lluvias intensas, lo más seguro es evitar o restringir los trayectos por la zona afectada para no exponerse a riesgos innecesarios como el aquaplaning o la baja visibilidad. Reducir la masa a transportar no es una medida directa para la seguridad en caso de lluvia intensa, ya que el problema principal es la adherencia y la visibilidad. Tampoco es recomendable reducir la presión de los neumáticos, ya que esto puede afectar negativamente la estabilidad y el control del vehículo.', NULL),
('cap-9243dbbf4c19', 'En los transportes en colaboración, el transportista que contrata directamente con el cargador original asume el rol de cargador frente al transportista que le ayuda a realizar el servicio. Esto significa que el transportista principal es quien encarga el transporte al colaborador. El RD 1211/1990 Art. 48 no es relevante para esta pregunta, ya que trata sobre las funciones de la Dirección General de Transporte Terrestre. No es un operador de transportes, porque esa figura tiene otras funciones y responsabilidades distintas a la de encargar un transporte a otro transportista.', 'RD 1211/1990 Art. 48'),
('cap-924f08a3ef52', 'La Ergonomía es una ciencia multidisciplinar que busca adaptar el puesto de trabajo a la persona. Para ello, necesita conocimientos de Anatomía para entender la estructura del cuerpo, de Fisiología para comprender su funcionamiento y de Psicología para analizar los procesos mentales y el comportamiento. Por tanto, todas estas ciencias son fundamentales para la Ergonomía.', NULL),
('cap-925f3eb07df9', 'La deriva del neumático es el ángulo que se forma entre la dirección de la rueda y la dirección real de avance del vehículo. Este fenómeno aumenta con la velocidad porque a mayor velocidad, las fuerzas laterales que actúan sobre el neumático son mayores, deformándolo más. Las otras opciones mencionan conceptos que no tienen relación directa con la deriva del neumático en la conducción.', NULL),
('cap-9265ff6cf72c', 'Las autorizaciones de transporte con clave MDLE son de ámbito nacional. Esto significa que permiten realizar transporte en todo el territorio español, sin restricciones de distancia o geográficas. La OM FOM/734/2007 Art. 6 confirma que estas autorizaciones habilitan para operar en todo el territorio del Estado sin limitaciones de radio de acción. Pensar que solo se puede transportar en el municipio o en la Comunidad Autónoma de residencia es un error, ya que la autorización MDLE no tiene esas restricciones.', 'OM FOM/734/2007 Art. 6'),
('cap-928392b62eb9', 'Sí, el número de revoluciones por minuto del motor influye directamente en el consumo de carburante. A menos revoluciones, el motor necesita menos combustible para funcionar, lo que se traduce en un menor consumo. Es importante buscar la zona de par máximo del motor para una conducción eficiente. La idea de que solo influye por encima de ciertas revoluciones es incorrecta, ya que el consumo varía en todo el rango de funcionamiento del motor.', NULL),
('cap-9286c90a902b', 'Interrumpir la conducción cada dos horas o 200 km permite descansar la vista y el cuerpo, lo que ayuda a mantener la concentración y a reducir la fatiga. Esto es fundamental para prevenir la aparición del sueño y sus peligrosos efectos al volante. Adoptar una postura relajada o recostada, mantener una temperatura elevada en el vehículo o realizar comidas copiosas son prácticas que, por el contrario, favorecen la somnolencia y aumentan el riesgo de accidente.', NULL),
('cap-92a8c1eccdc3', 'El conductor es la cara visible de la empresa durante las inspecciones en carretera, ya que es quien interactúa directamente con los agentes y presenta la documentación del vehículo y la carga. Aunque no tiene poder para tomar decisiones estratégicas, su actuación es crucial para el buen desarrollo de la inspección. El conductor sí representa a la empresa en estas situaciones, por lo que la afirmación de que en ningún caso la representa es incorrecta.', NULL),
('cap-92a985d0f54b', 'El mantenimiento adecuado del vehículo, una conducción eficiente y mantener el motor en el rango óptimo de revoluciones son factores clave que influyen directamente en el consumo de carburante. Un vehículo bien mantenido reduce la resistencia y optimiza la combustión. La forma de conducir, anticipándose y evitando aceleraciones y frenadas bruscas, también es fundamental para ahorrar combustible. El tipo de ralentizador que monte el vehículo no tiene un impacto directo en el consumo de carburante.', NULL),
('cap-92d51df60029', 'El freno motor-Veb es un tipo de freno motor que actúa directamente sobre las válvulas de escape de los cilindros, cerrándolas en la fase de escape para retener los gases y generar una contrapresión que frena el motor. Los otros ralentizadores, como el retárder, el intárder o el freno eléctrico, actúan sobre la transmisión o el eje, no directamente sobre las válvulas del motor.', NULL),
('cap-92f0467a5804', 'Para una circulación segura, es fundamental estar atento a todo lo que ocurre alrededor del vehículo, señalizar correctamente cualquier movimiento que vayas a hacer y realizar esas maniobras de forma controlada y exacta. Mantener una distancia de seguridad reducida es muy peligroso, ya que no te da tiempo a reaccionar ante imprevistos. Observar las maniobras y advertir al entorno está al revés, primero se advierte y luego se ejecuta. Mantener una velocidad de crucero estable no garantiza la seguridad por sí solo, hay que adaptarse a las circunstancias.', NULL),
('cap-92f3a5f45f7b', 'Los vehículos pesados, por su gran masa y tamaño, generan una energía cinética mucho mayor en caso de impacto, lo que aumenta la gravedad de las lesiones y la probabilidad de víctimas mortales. Además, su mayor distancia de frenado y la dificultad para maniobrar rápidamente contribuyen a que, cuando se ven implicados en un accidente, las consecuencias sean más graves. Pensar que es inferior es un error, ya que su tamaño y peso son factores de riesgo importantes.', NULL),
('cap-92f87f9ab662', 'Los manguitos y mangas son elementos que cubren y protegen específicamente los brazos, y a veces también las manos, de riesgos como cortes, abrasiones o salpicaduras. Por lo tanto, se clasifican como protectores de manos y brazos. Los protectores de pies y piernas, o los de ojos y cara, cubren otras partes del cuerpo distintas a los brazos. Los protectores de las vías respiratorias están diseñados para proteger contra la inhalación de sustancias nocivas, no para la protección física de los brazos.', 'RD 773/1997 Anexo I'),
('cap-930c5e84823c', 'El perfil de la carretera, es decir, si hay subidas, bajadas o tramos llanos, influye directamente en la resistencia que el motor debe vencer y, por tanto, en la cantidad de carburante que necesita para mantener la velocidad. Conducir cuesta arriba siempre requerirá más combustible. El octanaje es una característica de la gasolina, no del gasóleo, y no afecta al consumo en un motor diésel.', NULL),
('cap-932f06c1007b', 'El sobreviraje ocurre cuando las ruedas traseras pierden adherencia y el vehículo tiende a girar más de lo que el conductor indica con el volante, cerrando la trayectoria. Esto puede llevar a que la parte trasera del camión se desplace hacia el exterior de la curva. La trayectoria más abierta de la que debería realizar se conoce como subviraje, que es lo contrario.', NULL),
('cap-9332a972b41a', 'El mantenimiento general del vehículo, una conducción eficiente y el buen estado del filtro de aire son factores clave que influyen directamente en el consumo de carburante. Un filtro de aire sucio, por ejemplo, dificulta la entrada de aire al motor, lo que aumenta el consumo. Los frenos, ya sean de tambor o de disco, no tienen un impacto directo en el consumo de carburante.', NULL),
('cap-933e587a0dfe', 'La potencia de un motor se mide en kilovatios, que es la unidad estándar para expresar la capacidad de trabajo de una máquina en un tiempo determinado. Los amperios miden la intensidad de corriente eléctrica, no la potencia del motor. Los kilómetros por hora miden la velocidad, no la potencia.', NULL),
('cap-937a56fe663b', 'Los aparatos de control de tiempos de conducción y descanso se clasifican en analógicos y digitales. Los tacógrafos analógicos utilizan hojas de registro para guardar la información, mientras que los tacógrafos digitales emplean tarjetas de tacógrafo. Esta distinción es fundamental para entender cómo se registran los datos de actividad del conductor, tal como se define en el Reglamento Comunitario (UE) 165/2014 Art. 2.2 g y h. Las opciones que mencionan tipos como "electrónicos", "magnéticos" o "eléctricos" no corresponden a la clasificación oficial de los aparatos de control.', 'Reglamento Comunitario (UE) 165/2014 Art. 2.2 g y h'),
('cap-93877dcb726f', 'El EDS es un sistema de control de tracción que actúa sobre las ruedas motrices. Su función principal es evitar que una rueda patine al arrancar o acelerar, frenándola individualmente para transferir el par a la rueda con mayor adherencia. Esto mejora la capacidad de tracción del vehículo. La opción que habla de la distancia con el vehículo de delante se refiere a sistemas de asistencia a la conducción como el control de crucero adaptativo, no al EDS.', NULL),
('cap-938f344de246', 'Mantener una distancia de seguridad amplia te da más tiempo para reaccionar ante cualquier imprevisto. Esto te permite frenar o reducir la velocidad de forma suave y progresiva, evitando frenazos bruscos que disparan el consumo de combustible. La distancia de seguridad no solo influye en la seguridad, sino también en la eficiencia del consumo. La idea de que una distancia corta permite observar antes los imprevistos es incorrecta, ya que reduce el tiempo de reacción.', NULL),
('cap-93bd41fc4bae', 'Las actividades en el tacógrafo analógico deben grabarse en la hora del país de matriculación del vehículo. Esto es fundamental para asegurar la coherencia y facilitar los controles, ya que el Reglamento Comunitario (UE) 165/2014 Art. 34.5 establece que los conductores deben velar por la concordancia entre el marcado horario de la hoja de registro y la hora oficial del país de matriculación del vehículo. Grabar en hora UTC o en la hora local de cada país por el que se circule generaría inconsistencias y dificultaría la supervisión de los tiempos de conducción y descanso.', 'Reglamento Comunitario (UE) 165/2014 Art. 34.5'),
('cap-93e288220d79', 'El estilo de conducción es el factor más importante que influye en el consumo de carburante, ya que una conducción eficiente, sin acelerones ni frenazos bruscos, reduce significativamente el gasto. La posición del conductor no tiene ninguna influencia directa en el consumo de combustible. El octanaje es una medida de la resistencia a la detonación de la gasolina, no del gasóleo, y no afecta al consumo en un motor diésel. La relación de compresión es un valor fijo del motor y no varía con las revoluciones.', NULL),
('cap-93e3527a1e01', 'El conductor percibe directamente las vibraciones y ruidos que genera el propio vehículo, lo que le da información sobre su funcionamiento y posibles anomalías. El estado del firme de la carretera es una información del entorno, no del vehículo en sí. La velocidad de vehículos cercanos y las condiciones de luminosidad son también informaciones del entorno exterior, no internas del vehículo.', NULL),
('cap-93ea84f3fcda', 'La tarjeta de centro de ensayo es la única que permite probar, activar y calibrar el tacógrafo digital, tal como se especifica en la OM FOM/1190/2005 Art. 2. Las tarjetas de conductor, empresa y control tienen funciones diferentes, como identificar al conductor, gestionar datos de la empresa o realizar inspecciones. La tarjeta de control, por ejemplo, solo permite acceder a la información para su lectura, impresión o transferencia, no para calibrar.', 'OM FOM/1190/2005 Art. 2'),
('cap-9421cfb03d63', 'La descarga de datos de la unidad intravehicular del tacógrafo digital es obligatoria en varias situaciones. Se debe hacer antes de transferir el vehículo a otro titular, cuando se detecta un mal funcionamiento para preservar la información, y siempre que la Administración lo requiera para sus controles. Por lo tanto, todas las situaciones mencionadas son motivos válidos para realizar la descarga.', NULL),
('cap-944113176e59', 'Es fundamental verificar que el extintor es el apropiado para el tipo de fuego (clase A, B, C, D o F) antes de usarlo, ya que un agente extintor incorrecto puede ser ineficaz o incluso peligroso. La idea de que cualquier extintor sirve para cualquier incendio es un error grave, pues cada tipo de fuego requiere un agente extintor específico. Colocarse de cara al viento es incorrecto porque el viento arrastraría el agente extintor hacia ti, impidiendo que llegue al fuego y poniéndote en riesgo.', NULL),
('cap-947e123b73cf', 'El jefe de tráfico es el responsable de organizar y coordinar los vehículos y conductores para cumplir con los servicios de transporte. Su función principal es optimizar las rutas y los recursos disponibles para asegurar la eficiencia y rentabilidad de la operación. El conductor ejecuta la ruta planificada, no la diseña. El gerente tiene una visión más estratégica y el comercial se enfoca en la captación de clientes, no en la planificación operativa diaria.', NULL),
('cap-947e395043b8', 'Las empresas no pueden pagar a los conductores por kilómetros si esto les lleva a incumplir los tiempos de conducción y descanso. El Reglamento Comunitario (CE) 561/2006 Art. 10.1 prohíbe expresamente estas primas si comprometen la seguridad o fomentan infracciones. La opción que dice que sí se puede siempre es incorrecta, ya que la ley pone límites claros a este tipo de remuneración.', 'Reglamento Comunitario (CE) 561/2006 Art. 10.1'),
('cap-94a19be645ee', 'Los costes de los accidentes de tráfico, incluyendo los sanitarios, materiales y administrativos, suponen una carga económica muy importante para la sociedad. En países con rentas elevadas, como los de la Unión Europea, se estima que estos costes representan aproximadamente el 2% del Producto Nacional Bruto. Es un porcentaje significativo que demuestra el impacto económico de la siniestralidad vial. Otros porcentajes mucho más altos, como el 10%, el 15% o el 30%, serían cifras desproporcionadas y no se corresponden con la realidad económica de los accidentes.', NULL),
('cap-94c84d4217da', 'El perfil de la carretera, es decir, si es llana, cuesta arriba o cuesta abajo, es fundamental para decidir cuándo cambiar de marcha y optimizar el consumo. En una subida, por ejemplo, necesitarás una marcha más corta para mantener la fuerza, mientras que en una bajada puedes usar una marcha más larga o incluso dejar que el vehículo ruede. El coeficiente aerodinámico, el tipo de ralentizador o la anchura de los neumáticos no influyen directamente en el momento de cambiar de marcha para ahorrar combustible.', NULL),
('cap-94dd87c2e8a7', 'La competencia en el transporte se refiere a tener los conocimientos y las habilidades para realizar el servicio de forma adecuada y segura. Esto incluye saber manejar el vehículo, conocer las rutas y la normativa, y ser capaz de resolver problemas. La experiencia y los contactos son útiles, pero no definen la competencia en sí misma. Enmascarar un mal servicio es lo contrario a ser competente.', NULL),
('cap-954ca85b5dc5', 'El consumo de carburante depende directamente de cuánto pises el pedal del acelerador, ya que este controla la cantidad de combustible que se inyecta en el motor. Cuanto más se pisa, más combustible se demanda y, por tanto, mayor es el consumo. La situación de las ruedas motrices no influye directamente en el consumo, sino en la tracción del vehículo.', NULL),
('cap-95524adce3d7', 'En los cambios de rasante, la visibilidad es muy limitada y no se ve lo que viene de frente hasta que se está encima. Si un vehículo contrario está adelantando, puede invadir tu carril y provocar una colisión frontal. Por eso, hay que extremar la precaución y reducir la velocidad. La preocupación por la falta de combustible es una cuestión de planificación del viaje, no un riesgo directo de la vía.', NULL),
('cap-9568ae9f40e6', 'La posición de las diez y diez permite un control óptimo del volante, facilitando giros amplios y rápidos sin necesidad de cambiar la posición de las manos. Esta postura también ayuda a mantener los brazos ligeramente flexionados, lo que es crucial para reaccionar ante imprevistos y absorber impactos. La posición de las diez menos diez es incorrecta porque limita el rango de movimiento del volante y puede provocar una postura más rígida.', NULL),
('cap-95698b7dc2a0', 'El Reglamento Comunitario (CE) 561/2006 Art. 4.k define el tiempo diario de conducción como el tiempo total acumulado de conducción entre el final de un descanso diario y el inicio del siguiente, o entre un descanso diario y un descanso semanal. Esta definición es precisa y se basa en los periodos de descanso que delimitan la jornada de conducción. La conducción efectuada en 24 horas no es correcta porque el tiempo diario de conducción no siempre coincide con un periodo de 24 horas exactas, sino que está ligado a los descansos. La conducción acumulada de toda la semana se refiere al tiempo semanal de conducción, no al diario.', 'Reglamento Comunitario (CE) 561/2006 Art. 4.k'),
('cap-95701d63d4fe', 'Los vehículos dedicados exclusivamente a servicios de alcantarillado están exentos de usar tacógrafo. Esta exención está recogida específicamente en el RD 640/2007 Art. 2.c. No importa si el vehículo es municipal o si el desplazamiento es fuera del núcleo urbano, la exención se aplica por el tipo de servicio. La opción de un tacógrafo especial no existe para este tipo de transporte.', 'RD 640/2007 Art. 2.c'),
('cap-958836091608', 'El tipo de neumático, sea con cámara o sin ella, no afecta directamente al consumo de carburante. Lo que sí influye es la resistencia a la rodadura del neumático, que depende de su diseño, compuesto y, crucialmente, de la presión de inflado. El perfil de la carretera, la presión de los neumáticos y la posición del pedal del acelerador son factores que sí tienen un impacto directo y significativo en el consumo de combustible del vehículo.', NULL),
('cap-959c0f63f4e0', 'Cuando el nivel de circulación es negro por nieve, la Resolución D.G. Tráfico 01/06/2009 Anexo I recomienda no abandonar el vehículo si no se tiene la certeza de encontrar un refugio seguro. Esto se debe a que el vehículo ofrece protección contra el frío y la intemperie, y es más fácil de localizar por los servicios de emergencia. Abandonar el vehículo sin un refugio claro puede exponer al conductor a riesgos mayores como la hipotermia o la desorientación.', 'Resolución D.G. Tráfico 01/06/2009 Anexo I'),
('cap-95aaff7a296a', 'El tacógrafo analógico registra automáticamente la velocidad, la distancia recorrida y los tiempos de conducción y descanso del conductor en el disco. Sin embargo, la matrícula del vehículo no se registra de forma automática o semiautomática; es un dato que el conductor debe anotar manualmente en la hoja de registro. El Reglamento Comunitario (UE) 165/2014 Art. 4.3 especifica los datos que deben registrarse, y la matrícula no está entre los que se registran automáticamente. Pensar que la matrícula se registra automáticamente es un error común, pero el sistema no tiene esa capacidad.', 'Reglamento Comunitario (UE) 165/2014 Art. 4.3'),
('cap-95add69e9189', 'El RD 640/2007 Art. 2.o, apartado n), establece claramente que los transportes realizados por vehículos dedicados exclusivamente a servicios dentro de recintos cerrados como puertos o aeropuertos están exentos del uso del tacógrafo. Esto se debe a que la actividad principal no es el transporte por carretera en sí, sino el servicio dentro de un entorno controlado. Por tanto, no es necesario llevar tacógrafo ni calibrado ni especial. La titularidad del recinto, sea pública o privada, no influye en esta exención.', 'RD 640/2007 Art. 2.o'),
('cap-95d24a557787', 'El conductor está obligado a conducir el vehículo hasta el taller, acompañado por los agentes, y a facilitar las operaciones de verificación. Así lo establece la Ley 16/1987 Art. 33.4, que indica claramente esta obligación. La idea de que el conductor solo acompaña o que los agentes conducen el vehículo es incorrecta, ya que la ley exige la colaboración activa del conductor.', 'Ley 16/1987 Art. 33.4'),
('cap-95dfb8141dae', 'El TCS es un sistema de seguridad activa porque actúa antes de que se produzca un accidente, ayudando a mantener el control del vehículo al evitar la pérdida de tracción de las ruedas. Su función es prevenir situaciones de riesgo, como derrapes al acelerar. No es un elemento de seguridad pasiva, ya que estos últimos actúan durante o después de un accidente para minimizar sus consecuencias. Que no sea obligatoria su instalación no significa que no sea un elemento de seguridad.', NULL),
('cap-9600a0c43c20', 'El estilo de conducción influye directamente en el consumo de carburante. Una conducción eficiente, anticipándose al tráfico y evitando acelerones y frenazos bruscos, reduce significativamente el gasto. Por el contrario, una conducción agresiva o con marchas inadecuadas aumenta el consumo. Decir que solo depende de la cilindrada, del tipo de carburante o de la inclinación de la carretera es incorrecto, ya que estos son factores que influyen, pero no son los únicos ni anulan el impacto del estilo de conducción.', NULL),
('cap-960276012b86', 'Cuando un motor gira al máximo de revoluciones, ya ha superado el punto de su curva de potencia donde entrega el par motor máximo. A esas revoluciones tan altas, el par motor empieza a disminuir porque el llenado de los cilindros y la combustión ya no son tan eficientes. Por eso, el par motor es menor a máximas revoluciones que a un régimen medio. El par motor no es mayor a máximas revoluciones, ya que el par máximo se alcanza a un régimen intermedio.', NULL),
('cap-963bd3116872', 'El tacógrafo es el dispositivo homologado y obligatorio para registrar los tiempos de conducción y descanso de los conductores profesionales, así como la velocidad y la distancia recorrida. Su función principal es garantizar el cumplimiento de la normativa sobre tiempos de trabajo y descanso, fundamental para la seguridad vial y laboral. El limitador de velocidad, aunque también es un dispositivo de control, solo regula la velocidad máxima del vehículo, no los tiempos de actividad del conductor. El termógrafo se usa para registrar la temperatura en el transporte de mercancías perecederas, y el cuentarrevoluciones mide las revoluciones del motor, no los tiempos de conducción.', 'RD 2822/1998 Art. 11'),
('cap-963ec09d8c5a', 'El transporte en tránsito se refiere al paso de mercancías por un país sin que se carguen o descarguen en su territorio. Es simplemente un cruce para llegar a otro destino. El Reglamento Comunitario (CE) 1072/2009 Art. 2 lo incluye dentro de la definición de "transportes internacionales" cuando se atraviesa uno o más Estados miembros o terceros países. Un transporte triangular no es un término reconocido para esta situación específica.', 'Reglamento Comunitario (CE) 1072/2009 Art. 2'),
('cap-964ddf0f69d0', 'Una luxación es cuando un hueso se sale de su sitio en una articulación, perdiendo el contacto entre las superficies articulares. Esto provoca dolor intenso y la imposibilidad de mover la articulación afectada. No debe confundirse con la rotura de un músculo, que es un desgarro del tejido muscular.', NULL),
('cap-965b02bb35c7', 'La caja de velocidades sirve para que el motor trabaje en su régimen óptimo de revoluciones, que es la zona económica. Así se consigue el menor consumo de combustible y se alarga la vida útil del motor. Si el motor gira fuera de esa zona, el consumo se dispara y el desgaste aumenta. La caja de cambios no tiene relación con las turbulencias.', NULL),
('cap-9677b76725f8', 'Para pasar una zona inundada, hay que avanzar en primera y acelerar con suavidad para mantener un régimen de revoluciones constante y evitar que el agua entre en el tubo de escape. Si se pisa el embrague, se pierde el control del vehículo y se corre el riesgo de calarse. Acelerar en segunda para ganar velocidad puede provocar un aquaplaning o que el agua salpique el motor. Frenar en primera no es lo adecuado, ya que se necesita un impulso constante para superar la resistencia del agua.', NULL),
('cap-96b09096cb61', 'Antes de iniciar el viaje con un tacógrafo analógico, el Reglamento Comunitario (UE) 165/2014 Art. 34.6 exige que el conductor anote su nombre y apellidos, el lugar y la fecha de inicio, y la lectura del cuentakilómetros. Estos datos son fundamentales para el control de los tiempos de conducción y descanso. La opción que solo menciona el nombre y apellidos es incompleta, ya que faltan otros datos obligatorios.', 'Reglamento Comunitario (UE) 165/2014 Art. 34.6'),
('cap-96c145d68bb8', 'Los accidentes con forma no traumática son aquellos que no implican un golpe o una lesión física externa, sino que se deben a causas internas del organismo. Tanto los infartos como los derrames cerebrales son ejemplos claros de este tipo de accidentes, ya que son eventos súbitos que afectan al funcionamiento interno del cuerpo. Las hernias discales, aunque pueden ser incapacitantes, suelen estar relacionadas con un esfuerzo o un movimiento que provoca una lesión en la columna, lo que las clasifica como traumáticas.', NULL),
('cap-96c6079b7f26', 'La proyección de líquidos, especialmente si están calientes o son corrosivos, causa principalmente quemaduras o irritaciones en la piel. Los traumatismos son golpes o impactos, no el efecto directo de un líquido. Las rozaduras son por fricción, y las paradas cardíacas no son una consecuencia habitual de la proyección de líquidos.', NULL),
('cap-96f50ff177d3', 'La suspensión de un camión está diseñada para absorber las irregularidades del terreno, lo que se traduce directamente en una mejora del confort para el conductor y los ocupantes. Al reducir las vibraciones y los golpes, se consigue un viaje más cómodo y se disminuye la fatiga. Moderar la velocidad del vehículo no es una función directa de la suspensión, sino del sistema de frenos y la gestión del motor.', NULL),
('cap-96ff4bb4b4e5', 'Gran Bretaña no forma parte del Espacio Schengen, lo que significa que los controles fronterizos se mantienen para las personas que viajan desde o hacia este país. España, Suecia e Italia sí son miembros del Espacio Schengen, tal como se establece en el Acuerdo Adhesión de los reinos de España y Suecia y de la República Italiana al Convenio de aplicación del Acuerdo de Schengen. Art. 1. Confundir un país de la Unión Europea con un país del Espacio Schengen es un error común, pero no todos los países de la UE pertenecen a Schengen.', 'Acuerdo Adhesión de los reinos de España y Suecia y de la República Italiana al Convenio de aplicación del Acuerdo de Schengen. Art. 1'),
('cap-972fd67be240', 'El consumo específico es mínimo cuando el motor trabaja de forma más eficiente, lo que ocurre al régimen de par máximo. En ese punto, el motor aprovecha mejor el combustible para generar fuerza. Aunque la potencia no sea la máxima, la relación entre el trabajo realizado y el combustible consumido es óptima. No es cuando gira a la potencia máxima, ya que en ese momento el motor está forzado y el consumo de combustible por unidad de trabajo es mayor.', NULL),
('cap-973535235c44', 'El consumo de carburante aumenta con la velocidad porque la resistencia del aire, que es el principal factor a superar a velocidades elevadas, crece de forma exponencial. Esto significa que, a medida que la velocidad se duplica, la resistencia aerodinámica se cuadruplica, lo que exige mucha más energía y, por tanto, más combustible. Por eso, el consumo no aumenta en la misma proporción que la velocidad, sino en una proporción mucho mayor. El consumo no depende solo del coeficiente aerodinámico, sino también de la velocidad y otros factores.', NULL),
('cap-9739f9f0bafc', 'Los cursos de formación continua para el CAP tienen una duración establecida de 35 horas. Estas horas son necesarias para asegurar que los conductores profesionales actualizan sus conocimientos y habilidades periódicamente. Es importante no confundir esta duración con otras formaciones o permisos, ya que 30, 25 o 20 horas no son válidas para la renovación del CAP.', NULL),
('cap-973c5b19d5f9', 'La deriva del neumático es la deformación lateral que sufre la banda de rodadura al tomar una curva. Si la presión de inflado es baja, el neumático se deforma más y la deriva aumenta, afectando la estabilidad y el control del vehículo. Las fuerzas de atracción terrestre, gravedad y submotriz no tienen relación directa con la deformación lateral del neumático en curva.', NULL),
('cap-977323ef4aca', 'Según el RD Legislativo 8/2004 Art. 2.1.a, un vehículo tiene su estacionamiento habitual en España cuando tiene matrícula española, sin importar si es definitiva o temporal. La residencia del propietario o su nacionalidad no son los criterios que definen el estacionamiento habitual del vehículo a efectos del seguro obligatorio. Que el propietario resida en España más de 183 días al año no es el factor determinante para el estacionamiento habitual del vehículo.', 'RD Legislativo 8/2004 Art. 2.1.a'),
('cap-977ed51ddf26', 'En pendientes ascendentes, para optimizar el consumo, debes mantener el motor en su rango de eficiencia óptima, que es la parte derecha de la zona económica del tacómetro. Esto te permite aprovechar el par motor sin forzar el consumo excesivo. Circular a velocidad constante pisando más acelerador si fuera necesario es incorrecto porque un exceso de aceleración en subida dispara el consumo. Mantener el pedal acelerador poco pisado no es eficiente, ya que el motor no tendrá la fuerza necesaria y podrías perder velocidad y tener que reducir marcha, lo que también aumenta el consumo.', NULL),
('cap-97836fac8156', 'En un transporte en régimen de tránsito de la Unión, lo que se debe presentar en las aduanas de tránsito es el número de registro asignado a la declaración de tránsito, conocido como MRN. Así lo establece el Reglamento Comunitario (UE) 2015/2447 Art. 304, que indica que las mercancías deben presentarse junto con el MRN. No es necesario presentar la declaración de tránsito completa, ya que las aduanas de tránsito acceden a los datos de la operación a través del MRN. Presentar la declaración de tránsito es un error, ya que el sistema funciona con el número de referencia.', 'Reglamento Comunitario (UE) 2015/2447 Art. 304'),
('cap-97b7ad830938', 'La junta constituyente es la reunión inicial donde se formaliza la creación de la sociedad anónima, aprobando los estatutos y nombrando a los primeros administradores. Las juntas generales, sean ordinarias o extraordinarias, son reuniones que se celebran una vez que la sociedad ya está constituida y funcionando, para tratar asuntos de su gestión o cambios importantes.', NULL),
('cap-97d18f5157a0', 'Un asiento mal diseñado no absorbe correctamente las vibraciones y golpes, transmitiendo directamente los impactos a la base de la columna vertebral. Esto puede provocar lesiones importantes en la espalda del conductor. Los impactos no se dirigen principalmente a la cabeza, hombros o rodillas, ya que la columna es el eje central que soporta el peso y recibe la mayor parte de la carga en esta situación.', NULL),
('cap-97dac614eb0a', 'El ralentizador eléctrico funciona generando un campo magnético que frena el giro de un rotor conectado a la transmisión. Esto permite mantener las revoluciones de la transmisión en un régimen controlado, lo que ayuda a retener el vehículo sin usar los frenos de servicio. La opción de activar los cilindros del freno de servicio es incorrecta porque el ralentizador es un sistema de frenado auxiliar e independiente del freno de servicio.', NULL),
('cap-97e469e19d48', 'El sistema LKA (Lane Keeping Assist) está diseñado para mantener el vehículo dentro de su carril. Actúa sobre la dirección para corregir la trayectoria si detecta que el vehículo se desvía involuntariamente. Su objetivo principal es, por tanto, evitar que el vehículo se salga de la vía. La opción de alertar del riesgo de colisión frontal es una función de otro sistema, el FCW.', NULL),
('cap-98060ec8518a', 'El plazo máximo para la descarga de un vehículo de transporte de mercancías por carretera, una vez que ha llegado a su destino, es de una hora. Este tiempo se establece para agilizar las operaciones de carga y descarga y optimizar la eficiencia del transporte. Superar este plazo puede generar demoras y costes adicionales. Los plazos de dos, tres o cuatro horas son incorrectos y no se ajustan a la normativa habitual para estas operaciones.', NULL),
('cap-9816e2b8c488', 'La OM FOM/1190/2005 Art. 24 establece claramente que la descarga de datos de las tarjetas de los conductores debe hacerse, como mínimo, al abandonar el conductor la empresa. Esta es una de las situaciones obligatorias para asegurar la conservación de los datos. La opción de volcar la información semanalmente no es correcta, ya que la normativa exige un volcado al menos cada 31 días para evitar la sobreescritura, no semanalmente. Tampoco es correcto volcar la información solo al cambiar de vehículo, ya que la obligación de volcado de la tarjeta del conductor es independiente del vehículo que utilice.', 'OM FOM/1190/2005 Art. 24'),
('cap-982b378407e6', 'La tarjeta de cualificación de conductor tiene una vigencia máxima de cinco años. Esto se establece claramente en el RD 1032/2007 Art. 18, que indica que la tarjeta se expedirá con un período de vigencia máximo de cinco años. La opción de "cinco años, mínimo" es incorrecta porque la norma especifica un máximo, no un mínimo. La renovación de esta tarjeta se hace cada vez que el conductor supera un curso de formación continua.', 'RD 1032/2007 Art. 18'),
('cap-983898520543', 'El sistema IVMS (In-Vehicle Monitoring System) es el encargado de monitorizar y grabar el interior del vehículo, lo que permite verificar la correcta distribución de la carga y la seguridad. El VSTC no es un sistema de monitorización interior. El FCW es un sistema de aviso de colisión frontal. El ABSP no existe como sistema de control de carga.', NULL),
('cap-983d80d91e7f', 'Circular con las ventanillas bajadas aumenta la resistencia aerodinámica del vehículo, lo que obliga al motor a trabajar más para mantener la velocidad. Este esfuerzo extra se traduce directamente en un mayor consumo de carburante. Pensar que facilita el paso del aire es un error, ya que el aire que entra por las ventanillas crea turbulencias y resistencia.', NULL),
('cap-987201871cec', 'Un acuerdo multilateral es un pacto entre varios países, es decir, más de dos, para establecer las normas que rigen los permisos para hacer transportes internacionales. Estos acuerdos buscan simplificar y armonizar las condiciones para que los vehículos puedan circular entre los países firmantes. No se trata de acuerdos entre empresas, sino entre los propios estados. La idea de que los países deben tener una frontera común es incorrecta, ya que un acuerdo multilateral puede incluir países sin fronteras directas entre sí.', NULL),
('cap-987791e90c90', 'El contrato de transporte, tanto de mercancías como de viajeros, es siempre consensual. Esto significa que se perfecciona y es válido desde el momento en que las partes, transportista y cargador o viajero, llegan a un acuerdo, sin necesidad de que se entregue la mercancía o se pague el billete. La Ley Código de Comercio Art. 51 apoya este principio general. La idea de que solo es consensual en el transporte de mercancías o de viajeros, o que las mercancías peligrosas son una excepción, es incorrecta.', 'Ley Código de Comercio Art. 51'),
('cap-98bf84f04026', 'Debes empezar a reducir la velocidad una vez que ya estás dentro del carril de deceleración. Si empiezas a frenar antes de entrar en él, podrías entorpecer la circulación de los vehículos que vienen por detrás en la vía principal. Reducir la velocidad pisando el freno con la intensidad necesaria es una acción, pero no el momento adecuado para iniciar la reducción. Pisar el embrague para ayudar a la reducción de velocidad es un error porque te dejaría sin retención del motor, lo cual es peligroso.', NULL),
('cap-98c0f23f19f1', 'El perfil de la ruta es crucial porque determina la resistencia que el camión debe superar. No es lo mismo circular por llano que por pendientes pronunciadas, donde se necesita más fuerza y, por tanto, una relación de marchas más corta. La elección de la marcha adecuada permite al motor trabajar en su rango óptimo de revoluciones, evitando sobreesfuerzos y optimizando el consumo. La relación de engranajes del diferencial es un componente fijo del vehículo, no un factor que el conductor elija para la marcha en cada momento.', NULL),
('cap-98cc630f0b2f', 'El sistema SLI (Speed Limit Information) es el encargado de reconocer las señales de tráfico que indican límites de velocidad y mostrar esa información al conductor. Otros sistemas como el LKA (Lane Keeping Assist) o el LDW (Lane Departure Warning) están relacionados con el mantenimiento del carril, no con la velocidad. El ACC (Adaptive Cruise Control) es un control de crucero que adapta la velocidad, pero no se encarga de reconocer las señales de límite de velocidad.', NULL),
('cap-98cf3dcaf6d9', 'Para vehículos de transporte de mercancías con una MMA superior a 3.500 kg e inferior o igual a 10.000 kg, la normativa exige llevar un extintor de eficacia mínima 21A/113B. Esta medida garantiza una capacidad de extinción adecuada para fuegos comunes en este tipo de vehículos. La opción de llevar dos extintores de menor capacidad no sustituye la obligación de llevar uno con la eficacia mínima requerida.', 'OM 27/07/1999 Art. 2'),
('cap-98d7bdb78482', 'Cuando la memoria del tacógrafo digital se llena, los datos más recientes sobrescriben automáticamente a los más antiguos. Esto asegura que el tacógrafo siempre pueda registrar la actividad del conductor y del vehículo, manteniendo la información más actual disponible. La capacidad de la memoria está diseñada para un periodo determinado, pero no es ilimitada, por lo que la sustitución de datos es un mecanismo normal de funcionamiento. El tacógrafo no deja de funcionar ni registra un incidente por este motivo.', 'Reglamento Comunitario (UE) 165/2014 Anexo IB, apartado III, 12.3 (3821/85)'),
('cap-98fde4d9aa0e', 'El seguro obligatorio de responsabilidad civil no cubre los daños en los bienes de los familiares hasta tercer grado de consanguinidad o afinidad del conductor causante del accidente. Esta exclusión se aplica para evitar posibles fraudes o situaciones de connivencia. Por lo tanto, los bienes de estos parientes nunca estarán cubiertos por este seguro. La idea de que solo se excluyen si están en el vehículo es incorrecta, la exclusión se refiere a los bienes, no a la presencia física de los parientes.', NULL),
('cap-9917eb967afe', 'La falta de barandillas en plataformas elevadas provoca caídas desde altura. Estas caídas suelen resultar en impactos violentos contra el suelo o superficies duras, lo que con mayor frecuencia causa fracturas de huesos en distintas partes del cuerpo. Las lumbalgias o hernias discales son lesiones por esfuerzo o malas posturas, no por caídas desde altura.', NULL),
('cap-991f263946ac', 'El sistema PCS es un elemento de seguridad activa porque actúa antes de que se produzca un accidente, ayudando a prevenirlo o a mitigar sus consecuencias. Su función principal es detectar posibles colisiones y alertar al conductor, e incluso intervenir automáticamente para frenar o ajustar la dirección. No es un sistema pasivo, ya que estos últimos protegen a los ocupantes una vez que el impacto ya se ha producido.', NULL),
('cap-9929fb1dac04', 'El modo en que se utiliza el motor influye directamente en el consumo de carburante. Una conducción eficiente, con aceleraciones suaves y manteniendo un régimen de revoluciones adecuado, reduce el gasto. Por el contrario, una conducción agresiva o con el motor forzado aumentará el consumo. El consumo no depende únicamente de la velocidad, la relación de marchas o la aerodinámica, ya que el estilo de conducción es un factor determinante.', NULL),
('cap-9934f132ef97', 'Un sobreviraje ocurre cuando la trayectoria real del vehículo es más cerrada de lo que el conductor pretende en una curva. Esto significa que la parte trasera del vehículo tiende a deslizarse hacia el exterior de la curva, cerrando la trayectoria. El subviraje es lo contrario, cuando el vehículo tiende a seguir una trayectoria más abierta de la deseada.', NULL),
('cap-993974ac41a3', 'Los vehículos utilizados para el aprendizaje y la obtención del permiso de conducir o del CAP están exentos de usar tacógrafo. Esta exención se aplica porque su finalidad principal es la formación, no el transporte comercial de mercancías. El RD 640/2007 Art. 2.l lo especifica claramente. No importa la MMA del vehículo, la exención es total para estos casos.', 'RD 640/2007 Art. 2.l'),
('cap-99648c098efb', 'El estatuto de Operador Económico Autorizado (OEA) se concede a empresas que cumplen ciertos criterios de fiabilidad y seguridad en sus operaciones aduaneras. Esto les permite beneficiarse de un trato más favorable en los controles aduaneros, incluyendo menos controles físicos y documentales, tal como se indica en el Reglamento Comunitario (UE) 952/2013 Art. 38. La opción de una reducción especial en los gravámenes de importación no es una ventaja directa del OEA, ya que este estatuto no implica beneficios fiscales específicos.', 'Reglamento Comunitario (UE) 952/2013 Art. 38'),
('cap-998b9298cdf9', 'Conducir con anticipación te permite prever los movimientos del tráfico y las posibles paradas, lo que facilita una conducción más suave y eficiente. Esto ayuda a evitar frenazos bruscos y aceleraciones innecesarias, reduciendo el consumo de combustible y el desgaste del vehículo. No evitar las reducciones continuas de marchas es incorrecto porque precisamente hay que intentar minimizarlas para una conducción eficiente.', NULL),
('cap-99d362bcccb3', 'El consumo de carburante está directamente relacionado con el número de revoluciones del motor. A más revoluciones, el motor trabaja más rápido y, por lo tanto, necesita quemar más combustible para mantener ese ritmo. Por eso, para ahorrar carburante, siempre se busca conducir en la zona de par motor óptimo, que suele ser a bajas revoluciones. El consumo no solo depende de la carga o el volumen del vehículo, aunque estos factores también influyen, el régimen del motor es clave.', NULL),
('cap-9a077c8d2602', 'Conducir con anticipación te permite prever las situaciones del tráfico y evitar frenazos y aceleraciones bruscas, lo que reduce el consumo de carburante. Al mantener una velocidad más constante y usar menos el freno, el motor trabaja de forma más eficiente. Conocer el material del motor o la carrocería no influye directamente en el ahorro de carburante durante la conducción. Los datos técnicos exactos como el coeficiente aerodinámico o la carrera del pistón son importantes para el diseño del vehículo, pero no para la técnica de conducción que busca el ahorro.', NULL),
('cap-9a1150e4d8bd', 'Lo primero es asegurar la zona para evitar nuevos accidentes y proteger a todos. Después, hay que avisar a los servicios de emergencia para que acudan con los medios adecuados. Solo cuando la zona es segura y se ha pedido ayuda, se debe atender a las víctimas, ya que intentar ayudar antes de asegurar la zona o pedir asistencia puede poner en riesgo a más personas. La opción de ayudar a las víctimas primero es un error común, pero es peligroso porque la escena del accidente podría no ser segura.', NULL),
('cap-9a35691beaf7', 'El dióxido de carbono es el principal gas de efecto invernadero emitido por los vehículos de transporte por carretera, contribuyendo significativamente al cambio climático. Aunque los óxidos de nitrógeno también son contaminantes importantes, el dióxido de carbono se emite en mucha mayor cantidad en términos absolutos. El oxígeno carbónico no es una sustancia real, y el benzoato de bencilo es un compuesto orgánico sin relación directa con las emisiones de los motores de combustión.', NULL),
('cap-9a4030f25d07', 'Los transportistas tienen un papel activo en la lucha contra la inmigración ilegal. Están obligados a verificar que los extranjeros que transportan cumplen las condiciones de entrada al territorio Schengen, según el Convenio de Aplicación del Acuerdo de Schengen, Art. 26. No es una tarea exclusiva de la policía, sino una responsabilidad compartida. Tampoco depende del país de origen del viajero, sino de la normativa general del espacio Schengen.', 'Convenio Aplicación del Acuerdo de Schengen Art. 26'),
('cap-9a5ceb994550', 'El par motor no es máximo al régimen máximo del motor; el par máximo se alcanza a un régimen intermedio. Cuando el motor gira a su régimen máximo, el par motor ya ha empezado a disminuir, aunque sigue siendo superior al par mínimo. Por lo tanto, no es máximo ni tiene tendencia al mínimo, sino que se encuentra en un punto intermedio entre el mínimo y el máximo.', NULL),
('cap-9a5ee186b869', 'Una ventilación deficiente y una postura incómoda al volante son factores que contribuyen directamente a la aparición de la fatiga en el conductor. El aire viciado y una posición forzada aumentan el esfuerzo físico y mental, lo que reduce la concentración y el tiempo de reacción. La sed y el hambre son necesidades fisiológicas que, aunque importantes, no están directamente relacionadas con la ventilación o la postura.', NULL),
('cap-9a6174796a62', 'El retardador hidráulico debe usarse de forma progresiva para evitar movimientos bruscos del vehículo y garantizar un frenado suave y controlado. Un uso brusco podría desestabilizar el camión y la carga, además de someter el sistema a un estrés innecesario. No es un sistema para emergencias, sino un apoyo al freno de servicio para mantener la velocidad en descensos o reducirla de forma controlada.', NULL),
('cap-9a68ad97093c', 'Para reducir las revoluciones del motor y el consumo, debes usar marchas largas. Estas marchas permiten que el motor gire a menos revoluciones para mantener la misma velocidad, lo que se traduce en un menor consumo de combustible. Usar marchas cortas haría que el motor girara a más revoluciones, aumentando el consumo. Las bujías frías o el octanaje de la gasolina no influyen directamente en las revoluciones del motor para reducir el consumo.', NULL),
('cap-9a84084a8650', 'La mayoría de los accidentes mortales en jornada no son golpes o caídas, sino infartos o derrames cerebrales. Estos accidentes de forma no traumática representan el porcentaje más alto de muertes en el trabajo. El porcentaje del 36 al 45 % es el que mejor refleja esta realidad. Es un error pensar que la mayoría de las muertes son por traumatismos, ya que los problemas cardiovasculares son la principal causa.', NULL),
('cap-9a87691da66c', 'El ralentizador hidrodinámico, también conocido como intarder o retarder, utiliza la resistencia que ofrece un fluido, generalmente aceite, para frenar el vehículo. Este aceite se calienta al absorber la energía cinética del camión y luego se enfría en un intercambiador de calor. El freno eléctrico, por su parte, funciona mediante campos electromagnéticos, no con aceite.', NULL),
('cap-9a8e074504c9', 'El máximo aprovechamiento del combustible se consigue cuando el motor trabaja en la zona de régimen de par máximo. En este rango, el motor es más eficiente porque genera la mayor fuerza de giro con el menor consumo. Conducir en esta zona permite optimizar el consumo y reducir las emisiones. No es cuando el motor gira al máximo de revoluciones, ya que en ese punto el consumo de combustible es muy elevado y la eficiencia disminuye.', NULL),
('cap-9a8fa8732930', 'Según la Ley 16/1987 Art. 65, los transportes se clasifican en interiores e internacionales en función del ámbito geográfico en que se realicen. Los transportes interiores son los que tienen su origen y destino dentro de España, mientras que los internacionales discurren parcialmente por otros países. La clasificación de mercancías normales y peligrosas se refiere al tipo de carga, no al ámbito geográfico del transporte.', 'Ley 16/1987 Art. 65'),
('cap-9a9d1903dcc0', 'Arrancar en la marcha más baja posible es incorrecto porque transmite demasiada fuerza a las ruedas, lo que provoca que patinen y el vehículo no avance. Para arrancar sobre nieve, es mejor usar una marcha larga, como la segunda o tercera, para que la fuerza se distribuya de forma más suave y las ruedas tengan más agarre. Soltar el embrague lentamente es fundamental para evitar tirones y mantener la tracción.', NULL),
('cap-9ab15ed82324', 'El disco-diagrama es un documento personal e intransferible del conductor, como lo es la tarjeta de conductor en el tacógrafo digital. Cada conductor debe usar su propia hoja de registro para documentar sus actividades. La opción que indica que puede registrar actividades de dos conductores cuando hacen conducción en equipo es incorrecta, ya que cada conductor debe usar su propia hoja, incluso en equipo.', 'Reglamento Comunitario (UE) 165/2014 Art. 34'),
('cap-9ab31eb301fb', 'El aquaplaning es un fenómeno físico que ocurre cuando el neumático no es capaz de evacuar toda el agua que hay en la calzada, perdiendo el contacto con el asfalto. Esto puede ocurrirle a cualquier vehículo, independientemente de su peso o número de ejes, si la velocidad es excesiva para la cantidad de agua. Pensar que solo ocurre en vacío o con pocos ejes es un error, ya que la clave está en la velocidad y el diseño de la banda de rodadura.', NULL),
('cap-9aba10877e06', 'El freno motor en el escape funciona creando una contrapresión en el sistema de escape. Al limitar la salida de los gases, se genera una resistencia que dificulta el movimiento ascendente de los pistones, lo que a su vez frena el motor y, por tanto, el vehículo. La válvula de aceleración no sube ni baja de revoluciones, ya que su función principal es regular la entrada de aire al motor, no el frenado por escape.', NULL),
('cap-9ad57d29ceb8', 'El tacógrafo analógico registra la distancia recorrida con un estilete que se mueve de arriba abajo en la zona más interior del disco. Este movimiento marca la distancia en la hoja de registro. Las otras opciones no son correctas porque la distancia no se registra con números grandes ni en rojo, y el tacógrafo sí registra la distancia recorrida.', 'Reglamento Comunitario (UE) 165/2014 Anexo I, apartado III, c'),
('cap-9ad706467673', 'El Espacio Schengen es un área donde se han eliminado los controles en las fronteras interiores entre los países que lo forman, permitiendo la libre circulación de personas. Esto facilita mucho el transporte de mercancías y pasajeros por Europa. No incluye a todos los Estados miembros de la Unión Europea, ya que algunos no forman parte de él y otros que no son de la UE sí están. Tampoco es un espacio publicitario ni se refiere a la libre circulación entre continentes.', 'Acuerdo Schengen Art. 17'),
('cap-9ae810d5d210', 'La exposición continuada a vibraciones es el accidente relacionado con el transporte que se produce con mayor frecuencia porque muchos conductores profesionales están expuestos a ellas durante largas jornadas laborales. Estas vibraciones, aunque no causan un daño inmediato, pueden provocar problemas de salud a largo plazo, como lumbalgias o hernias discales. Los aplastamientos por vuelco de maquinaria, las descargas eléctricas o las proyecciones de líquidos son accidentes graves, pero su incidencia es mucho menor en comparación con la exposición diaria a vibraciones.', NULL),
('cap-9af7bcfbaeee', 'El Reglamento Comunitario (CE) 561/2006 Art. 4 define claramente la "semana" como el período de tiempo que va desde las 00:00 del lunes hasta las 24:00 del domingo. Esta es la definición oficial para el control de los tiempos de conducción y descanso. Un período de descanso diario o una jornada laboral son conceptos diferentes que se refieren a lapsos de tiempo más cortos dentro de esa semana. Un día civil es un concepto general que no se ajusta a la definición específica de semana para el transporte profesional.', 'Reglamento Comunitario (CE) 561/2006 Art. 4'),
('cap-9b008a7cb348', 'El ABS es un sistema de seguridad activa diseñado para evitar que las ruedas se bloqueen durante una frenada brusca. Al evitar el bloqueo, el conductor mantiene el control de la dirección del vehículo, lo que es crucial para esquivar obstáculos o mantener la trayectoria. La opción que dice que no permite frenar un vehículo salvo en emergencia es incorrecta, ya que el ABS asiste la frenada en cualquier situación para mejorar la seguridad.', NULL),
('cap-9b117b196c66', 'Cuando la suma de las fuerzas y los pares de fuerzas que actúan sobre un camión es distinta de cero, significa que hay una fuerza neta o un par neto que provoca un cambio en su estado de movimiento. Si el camión estaba en reposo, empezará a moverse. Si ya estaba en movimiento, su velocidad o dirección cambiarán. Que el vehículo se encuentre en reposo es incorrecto, ya que una fuerza neta siempre produce un cambio de estado.', NULL),
('cap-9b1b8e5f6d77', 'El freno eléctrico, también conocido como ralentizador eléctrico o Telma, actúa sobre la transmisión del vehículo, generalmente en el árbol de transmisión. Su funcionamiento se basa en la creación de un campo electromagnético que frena el giro de este eje, ralentizando el vehículo de forma suave y continua. No actúa sobre los elementos de fricción del freno de servicio, como los discos o tambores, lo que evita su sobrecalentamiento y desgaste. Tampoco actúa sobre las ruedas delanteras, ya que su función es auxiliar y complementaria al sistema de frenado principal.', NULL),
('cap-9b4e52d4e0e5', 'El consumo de carburante está directamente relacionado con las revoluciones por minuto del motor. A más revoluciones, el motor realiza más ciclos de combustión por unidad de tiempo y, por tanto, inyecta y quema más combustible. Mantener el motor en el rango de revoluciones óptimo para cada situación es clave para un consumo eficiente. La posición del conductor no influye en el consumo, y el octanaje es una medida de la resistencia a la detonación de la gasolina, no del gasóleo.', NULL),
('cap-9b55fd2afe43', 'El consumo de carburante aumenta con una conducción agresiva, con aceleraciones y frenadas bruscas, y también si el motor trabaja a revoluciones elevadas. Mantener el motor en su rango óptimo de revoluciones y una conducción suave son clave para ahorrar combustible. La longitud del pistón o del cigüeñal son características fijas del motor que no varían el consumo en función de su uso.', NULL),
('cap-9bb3ef5d6547', 'Cuando hay varias Juntas Arbitrales implicadas en una misma controversia, la norma establece que la competente es la primera que recibió el caso. Las demás Juntas deben abstenerse y dejar que la primera se encargue. Esto asegura que no haya duplicidad de actuaciones y se agilice la resolución. La opción que menciona el lugar de carga o el domicilio del transportista no es correcta en este escenario de conflicto de competencias entre Juntas, ya que esas son opciones para el demandante al inicio, no para resolver qué Junta es competente si ya hay varias implicadas.', 'RD 1211/1990 Art. 7.2'),
('cap-9bbf31303fdb', 'Una bajada de temperatura aumenta el consumo de combustible porque el motor necesita más energía para alcanzar su temperatura óptima de funcionamiento. Además, el aire frío es más denso, lo que requiere una mayor cantidad de combustible para mantener la mezcla aire-combustible adecuada. Pensar que no afecta al consumo es un error, ya que las condiciones ambientales siempre influyen en la eficiencia del motor.', NULL),
('cap-9bdc6fc477db', 'La OM FOM/1190/2005 Art. 24 establece claramente que la descarga de datos de las tarjetas de los conductores debe hacerse, como mínimo, al abandonar el conductor la empresa. Esta es una de las situaciones específicas que la normativa exige para asegurar la correcta conservación de los datos. Las opciones de volcado semanal o diario son incorrectas, ya que la normativa exige un volcado al menos cada 31 días, no con mayor frecuencia obligatoria. La opción que combina «Al abandonar la empresa» y «Todas las semanas» es incorrecta porque la frecuencia semanal no es un requisito legal para el volcado de la tarjeta del conductor.', 'OM FOM/1190/2005 Art. 24'),
('cap-9c05c2b42604', 'Los nutrientes son esenciales para el cuerpo porque nos dan la energía que necesitamos para vivir y movernos. También son los "ladrillos" que construyen y reparan nuestros órganos y tejidos. Además, los nutrientes actúan como reguladores, asegurando que todos los procesos internos del organismo funcionen correctamente. Por eso, todas las funciones mencionadas son correctas.', NULL),
('cap-9c39ae7f2872', 'Cuando se cumplen esas condiciones, los motores modernos cortan la inyección de combustible. Esto significa que no se consume nada de carburante, por lo que el consumo es nulo. Si se pisara el embrague o el acelerador, o si la velocidad fuera inferior a 20 km/h, el motor sí consumiría combustible para mantenerse encendido. El consumo no es mayor que al ralentí, ya que en ralentí el motor sí está inyectando combustible para mantenerse en marcha.', NULL),
('cap-9c48c7479f88', 'La Ley Orgánica 4/2000, en sus artículos 54 y 66, establece claramente que la responsabilidad por infracciones de extranjería recae en los transportistas que sean autores o partícipes. Esto incluye la obligación de comprobar la documentación de los extranjeros y hacerse cargo de ellos si se les deniega la entrada. Los conductores no son los únicos responsables, ya que la ley atribuye la obligación a la compañía o empresa de transporte. Los extranjeros transportados no son responsables de las infracciones de la normativa de extranjería en este contexto.', 'Ley Orgánica 4/2000 Arts. 54 y 66'),
('cap-9c6bab7991a9', 'El Reglamento Comunitario (CE) 561/2006 Art. 6.2 establece claramente que el tiempo de conducción semanal no puede superar las 56 horas. Este límite es fundamental para garantizar la seguridad en carretera y el descanso adecuado del conductor. Superar las 56 horas semanales es una infracción grave. Las 65 horas son un error común, pero no se ajusta a la normativa.', 'Reglamento Comunitario (CE) 561/2006 Art. 6.2'),
('cap-9c92cc9a73e8', 'Los equipos de protección individual deben incluir siempre instrucciones de uso para que el trabajador sepa cómo utilizarlos correctamente y garantizar su seguridad. Sin estas instrucciones, el equipo podría usarse mal y no proteger eficazmente. El certificado ISO 2350 no es un requisito de comercialización obligatorio para todos los EPI, y una maleta para guardarlos es un extra, no un elemento obligatorio que deba acompañar al equipo.', NULL),
('cap-9c9348bd3d18', 'La seguridad del servicio es fundamental, ya que un conductor que cumple las normas de seguridad y maneja con precaución transmite confianza. La competencia del conductor, demostrada en su habilidad para resolver problemas y su conocimiento de la ruta, también influye directamente en la percepción del cliente. Finalmente, la empatía en el trato, es decir, la capacidad de entender y responder a las necesidades del cliente, mejora significativamente la experiencia. Por lo tanto, todas las opciones contribuyen a la calidad del servicio percibida por el cliente.', NULL),
('cap-9cdde14e3dd6', 'Un vehículo se considera implicado en un accidente sin colisión si está parado o estacionado de forma peligrosa y esto contribuye al accidente. La OM INT/2223/2014 Anexo II, A) 2, apartado c) lo especifica claramente. Estar detenido ayudando o ser testigo no te convierte en implicado a efectos estadísticos.', 'OM INT/2223/2014 Anexo II, A) 2'),
('cap-9cf147395e79', 'El certificado de aptitud profesional lo expiden los órganos competentes para otorgar las autorizaciones de transporte público discrecional de viajeros y mercancías. Esto se debe a que el CAP es un requisito para obtener dichas autorizaciones, por lo que son las mismas autoridades las que lo gestionan. La Dirección General de Tráfico no es la encargada de registrar el CAP, su función es otra dentro del ámbito de la seguridad vial.', 'RD 1032/2007 Art. 3'),
('cap-9cf3a4119233', 'Cuando las ruedas se bloquean al frenar, el vehículo pierde la dirección y la capacidad de frenado. Para recuperar el control, hay que levantar el pedal del freno poco a poco hasta que las ruedas vuelvan a girar y recuperen la adherencia. Pisar el freno a fondo solo empeoraría el bloqueo y la pérdida de control.', NULL),
('cap-9d093a2757b3', 'Las letras IR identifican a un vehículo isotermo reforzado. Esto significa que tiene un aislamiento térmico superior al de un isotermo normal, lo que le permite mantener mejor la temperatura interior. Un isotermo normal se identifica solo con la letra I. Las letras R se utilizan para vehículos refrigerados, no isotermos.', 'Acuerdo ATP Anejo I, Apéndice 4'),
('cap-9d2a5e80bb68', 'La lluvia crea una capa de agua entre el neumático y el asfalto, lo que reduce el agarre de las ruedas al pavimento. Esta menor adherencia hace que sea mucho más fácil que el vehículo patine o se deslice. Pensar que la adherencia aumenta es un error, ya que el agua siempre reduce la fricción necesaria para un buen agarre.', NULL),
('cap-9d3bdcebb6ac', 'El sistema AEBS está diseñado para detectar una posible colisión frontal y, si el conductor no reacciona a tiempo, activar automáticamente los frenos para reducir la velocidad o evitar el impacto. Su objetivo principal es la seguridad activa, interviniendo directamente en la frenada. Evaluar el estado de alerta del conductor es función de otros sistemas, no del AEBS.', NULL),
('cap-9d4b9983e4ca', 'Los tacógrafos analógicos registran la actividad en hojas de registro, mientras que los tacógrafos digitales utilizan papel para imprimir los datos cuando es necesario. Ambas afirmaciones son correctas porque cada tipo de tacógrafo requiere su consumible específico para registrar o mostrar la información. La opción que menciona discos-diagrama para el tacógrafo digital es incorrecta, ya que los discos-diagrama son exclusivos de los tacógrafos analógicos.', 'Reglamento Comunitario (UE) 165/2014 Art. 13'),
('cap-9d4d8ecd6a05', 'La longitud del cigüeñal es una característica de diseño interno del motor que no varía durante la conducción y, por lo tanto, no influye en el consumo de carburante. El número de revoluciones del motor, el perfil de la carretera y la presión de los neumáticos sí son factores que afectan directamente al consumo. Un error común es pensar que cualquier componente del motor influye en el consumo, pero solo los que afectan a su rendimiento o a la resistencia al avance lo hacen.', NULL),
('cap-9d50c50dcccd', 'El círculo de Kamm representa las fuerzas que actúan sobre el neumático en contacto con la carretera. En sus ejes se representan las fuerzas longitudinales, que son las de aceleración y deceleración, y las fuerzas transversales, que son las de giro. La opción de fuerzas de atracción terrestre y rozamiento es incorrecta porque la atracción terrestre no se representa en los ejes del círculo de Kamm.', NULL),
('cap-9d722ff2810d', 'A los quemados no se les debe quitar la ropa porque podría estar adherida a la piel y al retirarla arrancaríamos también la piel, empeorando gravemente la lesión y aumentando el riesgo de infección. Es mejor cubrir la quemadura con un paño limpio y húmedo. En el caso de los heridos sin pulso, la prioridad es iniciar las maniobras de reanimación cardiopulmonar, no quitarles la ropa.', NULL),
('cap-9d7aaad03e83', 'La sofocación busca eliminar el oxígeno del fuego. Recubrir el combustible con espuma, desplazar el oxígeno con CO2 o impedir la ventilación son métodos efectivos para lograrlo. Todas estas acciones cortan el suministro de oxígeno necesario para que el fuego se mantenga.', NULL),
('cap-9d86e4face5e', 'El polvo químico seco de los extintores ABC es muy eficaz para apagar fuegos de diferentes tipos, pero su composición y la forma en que se descarga pueden ser corrosivas o dejar residuos que dañen componentes electrónicos, motores o maquinaria de precisión. Por eso, aunque apagan el fuego, pueden estropear el equipo. La idea de que se pueden usar sin problema en cualquier equipo es incorrecta precisamente por ese riesgo de daño.', NULL),
('cap-9d971a9480c9', 'La ejecución forzosa de un laudo arbitral se puede solicitar al órgano judicial competente una vez que han transcurrido veinte días desde que se dictó el laudo. Este plazo es el establecido por la normativa para asegurar que el laudo ha tenido tiempo de ser cumplido voluntariamente. La opción de los 5 días es incorrecta, ya que ese plazo es demasiado corto y no se ajusta a lo que marca la ley para estos procedimientos.', 'RD 1211/1990 Art. 9.8'),
('cap-9daf9e6cfe01', 'La prima es el precio que el asegurado paga a la compañía de seguros por la cobertura, tal como se establece en la póliza. Es la contraprestación económica por la protección que ofrece el seguro. La Ley 50/1980 Art. 14 especifica que el tomador está obligado al pago de la prima. El riesgo es la posibilidad de que ocurra un evento dañoso, no el precio.', 'Ley 50/1980 Art. 14'),
('cap-9dbcbfe83845', 'Los vehículos de la Administración pública están exentos de usar tacógrafo si realizan actividades propias de la Administración. Esto se debe a que el RD 640/2007 Art. 2.a establece una excepción para los transportes oficiales. Las opciones que mencionan un límite de Masa Máxima Autorizada son incorrectas, ya que la exención para transportes oficiales no depende del peso del vehículo.', 'RD 640/2007 Art. 2.a'),
('cap-9dc9c7fce92f', 'En nivel amarillo por nieve, la Resolución D.G. Tráfico 01/06/2009 Anexo I prohíbe la circulación de camiones y vehículos articulados. Esta restricción se aplica a todos los camiones, independientemente de su MMA. La prohibición es total mientras dure el aviso de nivel amarillo, no solo hasta la puesta de sol, y no se permite circular a ninguna velocidad.', 'Resolución D.G. Tráfico 01/06/2009 Anexo I'),
('cap-9dccf1567827', 'Al seleccionar una marcha más larga, el motor trabaja a menos revoluciones para mantener la misma velocidad, lo que reduce el consumo de carburante. Esto se debe a que el motor es más eficiente en marchas largas y a bajas revoluciones. Por el contrario, una marcha más corta o un número de revoluciones alto implican un mayor esfuerzo del motor y, por tanto, un mayor consumo. Mantener pisado el embrague no es una técnica de conducción eficiente y no reduce el consumo.', NULL),
('cap-9dda545bd90a', 'El control electrónico del sistema de frenado es conocido como EBS, que son las siglas en inglés de Electronically controlled brake system. Este sistema mejora la respuesta y la eficacia de los frenos, especialmente en vehículos pesados. El Electronic stability program (ESP) es un sistema de seguridad que ayuda a mantener la trayectoria del vehículo, no el control del frenado en sí.', NULL),
('cap-9ddc058b7242', 'La posición de las diez y diez es la más adecuada porque permite un control óptimo del volante y una mayor capacidad de reacción ante imprevistos. Esta posición facilita giros amplios sin necesidad de soltar las manos del volante, lo que es crucial para la seguridad. Colocar las manos en las once y diez o las doce y diez reduce la capacidad de maniobra y puede provocar una reacción más lenta.', NULL)
) as v(id, explicacion, norma)
where preguntas.id = v.id::text;
